  v := coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_read'), 'ABSENT');
