UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('agent_posts_public_read','chat images public read','playlist covers are publicly readable','vs_media_read','agent_posts_admin_read','chat_images_owner_admin_read','playlist_covers_owner_admin_read','vs_media_owner_admin_read')), '(null)')::text AS val
UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('')), '(null)')::text AS val
UNION ALL SELECT 'inv.buckets_public_flags'::text AS name, coalesce((SELECT string_agg(b.id || '=' || b.public::text, ',' ORDER BY b.id) FROM storage.buckets b), '(null)')::text AS val;

-- 3. THE FIX
-- 1. drop the four bucket-wide LISTING policies (public buckets serve /storage/v1/object/public/<bucket>/<path> WITHOUT any SELECT policy, so public URLs keep working; these policies only let anyone list/select/download through the API)
DROP POLICY agent_posts_public_read ON storage.objects;
DROP POLICY "chat images public read" ON storage.objects;
DROP POLICY "playlist covers are publicly readable" ON storage.objects;
DROP POLICY vs_media_read ON storage.objects;
-- 2. owner/admin-scoped replacements (authenticated only; anon gets none)
-- agent-posts is written by service_role only (posts/, competitions/): admin-only SELECT.
CREATE POLICY agent_posts_admin_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (bucket_id = 'agent-posts' AND public.is_admin());
-- chat-images: the uploader (storage owner_id), the owner of the profile for profiles/<slug>/..., or an admin. (Paths are NOT uid-prefixed: profile.html uses profiles/<slug>/..., create-event.html event-flyers/...)
CREATE POLICY chat_images_owner_admin_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (bucket_id = 'chat-images' AND (owner_id = (SELECT auth.uid())::text OR ((storage.foldername(name))[1] = 'profiles' AND EXISTS (SELECT 1 FROM public.profile_owners po WHERE po.owner_id = (SELECT auth.uid()) AND po.profile_slug = (storage.foldername(name))[2])) OR public.is_admin()));
CREATE POLICY playlist_covers_owner_admin_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (bucket_id = 'playlist-covers' AND ((storage.foldername(name))[1] = (SELECT auth.uid())::text OR public.is_admin()));
CREATE POLICY vs_media_owner_admin_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (bucket_id = 'vs-entries' AND ((storage.foldername(name))[1] = (SELECT auth.uid())::text OR public.is_admin()));

