  ('sel.chat-images', 'chat_images_owner_admin_read', ARRAY['chat_images_owner_admin_read']::text[]),
  ('sel.playlist-covers', 'playlist_covers_owner_admin_read', ARRAY['playlist_covers_owner_admin_read']::text[]),
  ('sel.vs-entries', 'vs_media_owner_admin_read OR vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read', ARRAY['vs_media_owner_admin_read','vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read']::text[]),
  ('pol.agent_posts_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.chat_images_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.playlist_covers_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.vs_media_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.agent_posts_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('pol.chat_images_owner_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('pol.playlist_covers_owner_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('pol.vs_media_owner_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('ins.vs-entries', 'vs_media_insert', ARRAY['vs_media_insert']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P1: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
END
$post$;
DO $invcheck$
DECLARE bad text;
BEGIN
  SELECT string_agg(a.name, ', ') INTO bad FROM _kil17a_inv a JOIN (
    SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('agent_posts_public_read','chat images public read','playlist covers are publicly readable','vs_media_read','agent_posts_admin_read','chat_images_owner_admin_read','playlist_covers_owner_admin_read','vs_media_owner_admin_read')), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('')), '(null)')::text AS val
    UNION ALL SELECT 'inv.buckets_public_flags'::text AS name, coalesce((SELECT string_agg(b.id || '=' || b.public::text, ',' ORDER BY b.id) FROM storage.buckets b), '(null)')::text AS val
  ) b USING (name) WHERE a.val IS DISTINCT FROM b.val;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P1: INVARIANT CHANGED (the pack must change nothing else; transaction rolls back): %', bad; END IF;
END
$invcheck$;

-- 5. RETAINED OUTPUT: keep this result set with the change record (ok must be true on every row).
WITH a(name, actual) AS (
  SELECT 'req.is_admin_exists' AS name, coalesce((to_regprocedure('public.is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.is_admin_exec_authenticated' AS name, coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.is_admin()'), 'EXECUTE')::text), 'ABSENT') AS actual
  UNION ALL SELECT 'req.profile_owners_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['profile_slug','owner_id']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_owners') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.rls_objects_enabled' AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'req.foldername_exists' AS name, coalesce((to_regprocedure('storage.foldername(text)') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.no_bucketless_anon_select' AS name, coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (p.roles && ARRAY['public','anon']::name[]) AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) !~ 'bucket_id'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:agent-posts' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'agent-posts'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:chat-images' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'chat-images'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:playlist-covers' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'playlist-covers'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.bucket_public:vs-entries' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.agent-posts' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'agent-posts'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.chat-images' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'chat-images'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.playlist-covers' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'playlist-covers'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.agent_posts_admin_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_posts_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_owner_admin_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat_images_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.playlist_covers_owner_admin_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'playlist_covers_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_owner_admin_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.agent_posts_admin_read.tokens' AS name, coalesce((SELECT ((coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'agent-posts' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'is_admin')::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_posts_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_owner_admin_read.tokens' AS name, coalesce((SELECT ((coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'chat-images' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'owner_id' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'profile_owners' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'is_admin')::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat_images_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.playlist_covers_owner_admin_read.tokens' AS name, coalesce((SELECT ((coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'playlist-covers' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'foldername' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'is_admin')::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'playlist_covers_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_owner_admin_read.tokens' AS name, coalesce((SELECT ((coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'foldername' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'is_admin')::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'ins.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.is_admin_exists', 'true', ARRAY['true']::text[]),
  ('req.is_admin_exec_authenticated', 'true', ARRAY['true']::text[]),
  ('req.profile_owners_cols', '2', ARRAY['2']::text[]),
  ('req.rls_objects_enabled', 'true/false', ARRAY['true/false']::text[]),
  ('req.foldername_exists', 'true', ARRAY['true']::text[]),
  ('req.no_bucketless_anon_select', '0', ARRAY['0']::text[]),
  ('req.bucket_public:agent-posts', 'true', ARRAY['true']::text[]),
  ('req.bucket_public:chat-images', 'true', ARRAY['true']::text[]),
  ('req.bucket_public:playlist-covers', 'true', ARRAY['true']::text[]),
  ('req.bucket_public:vs-entries', 'true', ARRAY['true']::text[]),
  ('sel.agent-posts', 'agent_posts_admin_read', ARRAY['agent_posts_admin_read']::text[]),
  ('sel.chat-images', 'chat_images_owner_admin_read', ARRAY['chat_images_owner_admin_read']::text[]),
  ('sel.playlist-covers', 'playlist_covers_owner_admin_read', ARRAY['playlist_covers_owner_admin_read']::text[]),
  ('sel.vs-entries', 'vs_media_owner_admin_read OR vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read', ARRAY['vs_media_owner_admin_read','vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read']::text[]),
  ('pol.agent_posts_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.chat_images_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.playlist_covers_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.vs_media_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.agent_posts_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('pol.chat_images_owner_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('pol.playlist_covers_owner_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('pol.vs_media_owner_admin_read.tokens', 'true', ARRAY['true']::text[]),
  ('ins.vs-entries', 'vs_media_insert', ARRAY['vs_media_insert']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'POST' AS expected, 'POST' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
COMMIT;
